// NORMALIZE: maps an IMAP email or a chat webhook call into one schema.
// Mode: Run Once for Each Item. Never throws: bad input becomes ctx.invalid.
const cfg = $('⚙️ CONFIG').first().json;
const raw = $json;
const nowIso = new Date().toISOString();
const MAX_CHARS = Number(cfg.MAX_MESSAGE_CHARS) || 4000;

const isChat = raw.webhookUrl !== undefined || (raw.body !== undefined && raw.query !== undefined && raw.params !== undefined);
const uuid = () => {
  const h = [...Array(32)].map(() => Math.floor(Math.random() * 16).toString(16));
  h[12] = '4';
  h[16] = ((parseInt(h[16], 16) & 3) | 8).toString(16);
  return `${h.slice(0, 8).join('')}-${h.slice(8, 12).join('')}-${h.slice(12, 16).join('')}-${h.slice(16, 20).join('')}-${h.slice(20).join('')}`;
};
const clean = (s) => String(s ?? '').replace(/\r\n/g, '\n').replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, '').trim();
const isEmail = (s) => /^[^\s@<>()",;]+@[^\s@<>()",;]+\.[^\s@<>()",;]{2,}$/.test(String(s || ''));

const ctx = {
  requestId: uuid(),
  channel: isChat ? 'chat' : 'email',
  conversationId: null,
  customerName: null,
  customerEmail: null,
  sessionToken: null,
  subject: null,
  messageText: '',
  history: [],
  receivedAt: nowIso,
  receivedAtMs: Date.now(),
  email: null,
  chat: null,
  invalid: null,
};

if (isChat) {
  const headers = raw.headers || {};
  const body = (raw.body && typeof raw.body === 'object') ? raw.body : {};
  const origin = String(headers.origin || headers.Origin || '');
  const allowed = String(cfg.WEBHOOK_ALLOWED_ORIGINS || '*').split(',').map((s) => s.trim().replace(/\/$/, '')).filter(Boolean);
  const originOk = allowed.includes('*') || (origin !== '' && allowed.includes(origin.replace(/\/$/, '')));

  let convId = clean(body.conversationId);
  if (convId.startsWith('chat:')) convId = convId.slice(5);
  if (!/^[A-Za-z0-9-]{16,64}$/.test(convId)) convId = uuid();

  const token = clean(body.sessionToken);
  const email = clean(body.email).toLowerCase();

  ctx.conversationId = `chat:${convId}`;
  ctx.customerName = clean(body.name).slice(0, 120) || null;
  ctx.customerEmail = isEmail(email) ? email : null;
  ctx.sessionToken = /^[A-Za-z0-9._~+\/=-]{16,512}$/.test(token) ? token : null;
  ctx.subject = 'Website chat';
  ctx.messageText = clean(body.message).slice(0, MAX_CHARS);
  ctx.chat = { origin, pageUrl: clean(body.pageUrl).slice(0, 500) || null };

  if (!originOk) ctx.invalid = { httpStatus: 403, reason: 'origin_not_allowed', message: 'This website is not allowed to use the support chat.' };
  else if (!ctx.messageText) ctx.invalid = { httpStatus: 400, reason: 'empty_message', message: 'Please type a message.' };
} else {
  // Email Trigger (IMAP), format "resolved" (mailparser). "simple" is handled too.
  const fromObj = raw.from && typeof raw.from === 'object' ? raw.from : null;
  const fromText = typeof raw.from === 'string' ? raw.from : (fromObj?.text || '');
  const fromAddr = String(fromObj?.value?.[0]?.address || (fromText.match(/<([^>]+)>/) || [])[1] || fromText).trim().toLowerCase();
  const fromName = String(fromObj?.value?.[0]?.name || fromText.replace(/<[^>]+>/, '').replace(/"/g, '')).trim();

  const hdr = {};
  for (const [k, v] of Object.entries(raw.headers || raw.metadata || {})) {
    const line = String(v);
    hdr[k.toLowerCase()] = line.includes(':') ? line.slice(line.indexOf(':') + 1).trim() : line;
  }

  const messageId = String(raw.messageId || hdr['message-id'] || '').trim() || `<${uuid()}@generated.local>`;
  const inReplyTo = String(raw.inReplyTo || hdr['in-reply-to'] || '').trim() || null;
  let references = raw.references || hdr['references'] || [];
  if (typeof references === 'string') references = references.split(/\s+/).filter(Boolean);
  const rootId = references[0] || inReplyTo || messageId;

  const subject = clean(raw.subject) || '(no subject)';
  let text = clean(raw.text || raw.textPlain || '');
  if (!text && (raw.html || raw.textHtml)) {
    text = clean(String(raw.html || raw.textHtml).replace(/<style[\s\S]*?<\/style>/gi, '').replace(/<br\s*\/?>/gi, '\n').replace(/<\/p>/gi, '\n\n').replace(/<[^>]+>/g, '').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>'));
  }
  // Drop the quoted thread below the new reply.
  const cutMarkers = [/^On .{4,200}wrote:\s*$/m, /^-{2,}\s*Original Message\s*-{2,}/mi, /^From: .+$/m, /^_{10,}$/m];
  for (const re of cutMarkers) { const m = text.match(re); if (m && m.index > 0) text = text.slice(0, m.index); }
  text = text.split('\n').filter((l) => !l.startsWith('>')).join('\n').trim().slice(0, MAX_CHARS);

  ctx.conversationId = `email:${rootId}`;
  ctx.customerName = fromName && fromName.toLowerCase() !== fromAddr ? fromName.slice(0, 120) : null;
  ctx.customerEmail = isEmail(fromAddr) ? fromAddr : null;
  ctx.subject = subject.slice(0, 300);
  ctx.messageText = text;
  // Quoted original appended to the reply so the customer keeps the thread context.
  const quoteSrc = text.slice(0, 1500);
  const sentAt = raw.date ? new Date(raw.date).toUTCString() : 'earlier';
  const escHtml = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  ctx.email = {
    messageId,
    inReplyTo,
    references,
    replySubject: /^re:/i.test(subject) ? subject : `Re: ${subject}`,
    quotedText: `\n\nOn ${sentAt}, ${fromAddr} wrote:\n${quoteSrc.split('\n').map((l) => `> ${l}`).join('\n')}`,
    quotedHtml: `<br><div style="color:#57606a">On ${escHtml(sentAt)}, ${escHtml(fromAddr)} wrote:</div><blockquote style="margin:0 0 0 8px;padding-left:8px;border-left:3px solid #d0d7de;color:#57606a">${escHtml(quoteSrc).replace(/\n/g, '<br>')}</blockquote>`,
  };

  const ownAddress = String(cfg.SUPPORT_FROM_EMAIL || '').toLowerCase();
  const autoSubmitted = (hdr['auto-submitted'] || '').toLowerCase();
  const precedence = (hdr['precedence'] || '').toLowerCase();
  const isAutomated = (autoSubmitted && autoSubmitted !== 'no') || ['bulk', 'junk', 'list', 'auto_reply'].includes(precedence) ||
    !!hdr['x-autoreply'] || !!hdr['x-autorespond'] || /^(mailer-daemon|postmaster|no-?reply|do-?not-?reply|bounce)/i.test(fromAddr);

  if (!ctx.customerEmail) ctx.invalid = { httpStatus: 400, reason: 'no_sender_address', message: 'Email has no valid sender address.' };
  else if (ownAddress && fromAddr === ownAddress) ctx.invalid = { httpStatus: 400, reason: 'own_address', message: 'Email was sent by the support mailbox itself.' };
  else if (isAutomated) ctx.invalid = { httpStatus: 400, reason: 'automated_email', message: 'Auto-reply, bounce or bulk email ignored to prevent loops.' };
  else if (!ctx.messageText) ctx.invalid = { httpStatus: 400, reason: 'empty_message', message: 'Email body is empty.' };
}

// Chat requires an email so a teammate can follow up after an escalation.
if (!ctx.invalid && ctx.channel === 'chat' && !ctx.customerEmail) {
  ctx.invalid = { httpStatus: 400, reason: 'email_required', message: 'Please enter your email address so we can follow up.' };
}

return { json: { ctx } };

// ORACLE PLAN: decide whether this message may trigger a customer lookup.
//  - email: look up the sender's own address (the From header).
//  - chat:  only when the widget sent a session token; the token is verified
//           against Turso afterwards, and unverified results are discarded.
//  - otherwise no Oracle call is made at all.
// Mode: Run Once for Each Item.
const cfg = $('⚙️ CONFIG').first().json;
const ctx = $json.ctx;
const base = String(cfg.ORACLE_ORDS_BASE_URL || '').trim().replace(/\/+$/, '');

let lookupEmail = null;
if (ctx.channel === 'email') lookupEmail = ctx.customerEmail;
if (ctx.channel === 'chat' && ctx.sessionToken) lookupEmail = ctx.customerEmail;

return {
  json: {
    requestId: ctx.requestId,
    oracleRequest: {
      needed: !!(lookupEmail && base),
      configured: !!base,
      url: lookupEmail ? `${base}/support/customers/by-email/${encodeURIComponent(lookupEmail)}` : null,
      timeoutMs: Math.max(500, Math.min(10000, Number(cfg.ORACLE_LOOKUP_TIMEOUT_MS) || 4000)),
    },
  },
};

// ORACLE PARSE: turn the ORDS response (or timeout) into a status flag.
// status: ok | not_found | unavailable. Never throws.
// Mode: Run Once for Each Item.
const r = $json;
const req = r.oracleRequest || {};
let status = 'unavailable';
let customer = null;
let detail = null;

const code = Number(r.statusCode || 0);
let body = r.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { /* keep string */ } }

if (code === 200 && body && typeof body === 'object' && body.customer_id) {
  status = 'ok';
  customer = {
    customer_id: String(body.customer_id),
    full_name: body.full_name ?? null,
    email: String(body.email || '').toLowerCase(),
    plan: body.plan ?? null,
    status: body.status ?? null,
    created_at: body.created_at ?? null,
  };
} else if (code === 404) {
  status = 'not_found';
} else {
  const e = r.error;
  detail = code ? `HTTP ${code}` : (typeof e === 'string' ? e : e?.message || e?.code || 'timeout or network error');
}

return { json: { requestId: r.requestId, oracle: { status, customer, detail, lookupEmail: req.url ? decodeURIComponent(req.url.split('/by-email/')[1] || '') : null } } };

// TURSO LOAD: describe the reads for this message as plain SQL statements.
// The Hrana wire format is added later in "🗄️ Turso: Encode Pipeline".
// Mode: Run Once for Each Item.
const cfg = $('⚙️ CONFIG').first().json;
const ctx = $json.ctx;
const historyLimit = Math.max(0, Math.min(50, Number(cfg.HISTORY_MESSAGE_LIMIT) || 10));
const faqLimit = Math.max(1, Math.min(10, Number(cfg.FAQ_RESULT_LIMIT) || 5));

// Keywords for FAQ retrieval: lowercase words, stop words removed, simple plural stemming.
const STOP = new Set(('a about above after again all am an and any are as at be because been before being below between both but by can cannot could did do does doing down during each few for from further had has have having he her here hers him his how i if in into is it its itself just let me more most my myself no nor not now of off on once only or other our ours out over own please same she should so some such than thank thanks that the their them then there these they this those through to too under until up very was we were what when where which while who whom why will with would you your yours hello hi hey dear regards best kind team support help need want know get got im ive dont cant wont').split(' '));
const words = String(`${ctx.subject && ctx.channel === 'email' ? ctx.subject.replace(/^re:\s*/i, '') : ''} ${ctx.messageText}`)
  .toLowerCase()
  .replace(/[^a-z0-9\s-]/g, ' ')
  .split(/\s+/)
  .map((w) => w.replace(/^-+|-+$/g, ''))
  .filter((w) => w.length >= 3 && !STOP.has(w) && !/^\d+$/.test(w))
  .map((w) => (w.length > 4 && w.endsWith('ies') ? `${w.slice(0, -3)}y` : w.length > 4 && w.endsWith('s') && !w.endsWith('ss') ? w.slice(0, -1) : w));
const keywords = [...new Set(words)].slice(0, 8);

const statements = [
  {
    key: 'conversation',
    sql: 'SELECT id, channel, customer_email, customer_name, oracle_customer_id, created_at, updated_at FROM conversations WHERE id = ?',
    args: [ctx.conversationId],
  },
  {
    key: 'history',
    sql: 'SELECT role, body, created_at FROM (SELECT id, role, body, created_at FROM messages WHERE conversation_id = ? ORDER BY id DESC LIMIT ?) ORDER BY id ASC',
    args: [ctx.conversationId, historyLimit],
  },
];

if (keywords.length) {
  // FTS5 (if faq_fts exists) ranked by bm25; a missing table only fails this one statement.
  statements.push({
    key: 'faq_fts',
    sql: 'SELECT f.id, f.question, f.answer, f.tags FROM faq_fts JOIN faq f ON f.id = faq_fts.rowid WHERE faq_fts MATCH ? AND f.active = 1 ORDER BY bm25(faq_fts) LIMIT ?',
    args: [keywords.map((k) => `"${k.replace(/"/g, '')}"*`).join(' OR '), faqLimit],
  });
  // LIKE fallback: tag hits weigh 3, question hits 2.
  const score = keywords.map(() => "(CASE WHEN lower(tags) LIKE ? THEN 3 ELSE 0 END) + (CASE WHEN lower(question) LIKE ? THEN 2 ELSE 0 END)").join(' + ');
  const likeArgs = keywords.flatMap((k) => [`%${k}%`, `%${k}%`]);
  statements.push({
    key: 'faq_like',
    sql: `SELECT id, question, answer, tags, score FROM (SELECT id, question, answer, tags, (${score}) AS score FROM faq WHERE active = 1) WHERE score > 0 ORDER BY score DESC, id ASC LIMIT ?`,
    args: [...likeArgs, faqLimit],
  });
}

if (ctx.channel === 'chat' && ctx.sessionToken) {
  statements.push({
    key: 'session',
    sql: 'SELECT token, customer_email, oracle_customer_id, expires_at FROM session_tokens WHERE token = ? AND expires_at > ?',
    args: [ctx.sessionToken, new Date().toISOString()],
  });
}

// Runtime settings and prompts managed in the admin console. Cached for 30 s in the
// workflow's static data (production executions), so console edits apply within 30 s.
const cache = $getWorkflowStaticData('global');
const fresh = cache.runtime && Date.now() - cache.runtime.loadedAt < 30000;
if (!fresh) {
  statements.push({ key: 'runtime_settings', sql: 'SELECT key, value_json FROM settings', args: [] });
  statements.push({ key: 'runtime_prompts', sql: 'SELECT id, body, version FROM prompts', args: [] });
}

ctx.retrieval = { keywords };

return { json: { ctx, turso: { purpose: 'load_context', timeoutMs: 2000, statements } } };

// ASSEMBLE CONTEXT: join Turso + Oracle results per message and verify identity.
// Input: Turso items ({ ctx, turso }) and Oracle items ({ requestId, oracle }), appended.
// Mode: Run Once for All Items. Never throws; failures become status flags.
const items = $input.all().map((i) => i.json);
const nodeCfg = $('⚙️ CONFIG').first().json;
const cache = $getWorkflowStaticData('global');

// Runtime config: admin-console settings (Turso) override the ⚙️ CONFIG node; prompts likewise.
function buildRuntime(res) {
  const rows = res?.runtime_settings?.ok ? res.runtime_settings.rows : null;
  const prows = res?.runtime_prompts?.ok ? res.runtime_prompts.rows : null;
  if (!rows && !prows) return null;
  const s = {};
  for (const r of rows || []) { try { s[r.key] = JSON.parse(r.value_json); } catch (e) { /* skip bad row */ } }
  const p = Object.fromEntries((prows || []).map((r) => [r.id, r.body]));
  const cfg = {};
  const map = {
    confidence_threshold: 'CONFIDENCE_THRESHOLD', confidence_threshold_email: 'CONFIDENCE_THRESHOLD_EMAIL', confidence_threshold_chat: 'CONFIDENCE_THRESHOLD_CHAT',
    claude_model: 'CLAUDE_MODEL', gemini_model: 'GEMINI_MODEL', max_tokens: 'MAX_TOKENS', request_timeout_ms: 'LLM_TIMEOUT_MS',
    auto_reply_email: 'AUTO_REPLY_EMAIL', auto_reply_chat: 'AUTO_REPLY_CHAT', business_hours: 'BUSINESS_HOURS',
    blocked_senders: 'BLOCKED_SENDERS', blocked_keywords: 'BLOCKED_KEYWORDS', company_name: 'COMPANY_NAME', support_from_email: 'SUPPORT_FROM_EMAIL',
  };
  for (const [k, v] of Object.entries(map)) {
    if (s[k] === undefined || s[k] === '' ) continue;
    cfg[v] = s[k];
  }
  return { config: cfg, prompts: p, loadedAt: Date.now(), version: Object.values(p).length };
}
const oracleById = new Map(items.filter((j) => j.oracle && !j.ctx).map((j) => [j.requestId, j.oracle]));
const lower = (s) => String(s || '').trim().toLowerCase();

const ACCOUNT_INTENT = /(where('?s| is| are)? my|status of my|track(ing)? (my|the) (order|package|parcel)|my (last |latest |recent )?(order|package|parcel|delivery|shipment|refund|return|invoice|account|ticket|subscription|plan)|order (number|no\.?|#)|\b[A-Z]{2,4}-\d{4,}\b|has my .* (shipped|arrived)|when will my)/i;

const out = [];
for (const j of items) {
  if (!j.ctx) continue;
  const ctx = j.ctx;
  const res = j.turso?.results || {};
  const tursoOk = j.turso?.ok !== false;
  const oracle = oracleById.get(ctx.requestId) || { status: 'not_requested', customer: null, detail: null };

  // Runtime config (fresh from Turso, else the 30 s cache, else the CONFIG/PROMPTS nodes).
  const loaded = buildRuntime(res);
  if (loaded) cache.runtime = loaded;
  const runtime = loaded || cache.runtime || { config: {}, prompts: {}, loadedAt: 0 };
  ctx.runtime = { config: runtime.config, prompts: runtime.prompts, source: loaded ? 'turso' : cache.runtime ? 'cache' : 'nodes', loadedAt: runtime.loadedAt };
  const cfg = { ...nodeCfg, ...runtime.config };

  // Blocked senders are ignored entirely (email: silently; chat: 403).
  const sender = lower(ctx.customerEmail);
  const blocked = (Array.isArray(cfg.BLOCKED_SENDERS) ? cfg.BLOCKED_SENDERS : []).some((b) => {
    const x = lower(b);
    return x.startsWith('@') ? sender.endsWith(x) : x === sender;
  });
  if (blocked) ctx.invalid = { httpStatus: 403, reason: 'blocked_sender', message: 'This chat is not available.' };

  // Memory: ignore history that belongs to a different customer (forged thread or reused id).
  const conv = res.conversation?.rows?.[0] || null;
  let history = (res.history?.rows || []).map((m) => ({ role: m.role, body: m.body, created_at: m.created_at }));
  let historyIgnored = false;
  if (conv && conv.customer_email && ctx.customerEmail && lower(conv.customer_email) !== lower(ctx.customerEmail)) {
    history = [];
    historyIgnored = true;
    ctx.conversationId = `${ctx.channel}:${ctx.requestId}`;
  }
  ctx.history = history;

  // Knowledge base: FTS5 rows when available, else LIKE rows.
  const fts = res.faq_fts?.ok ? res.faq_fts.rows : [];
  const like = res.faq_like?.ok ? res.faq_like.rows : [];
  ctx.faq = (fts.length ? fts : like).map((f) => ({ id: f.id, question: f.question, answer: f.answer, tags: f.tags }));
  ctx.retrieval = { ...(ctx.retrieval || {}), method: fts.length ? 'fts5' : like.length ? 'like' : 'none', count: ctx.faq.length };

  // Session token (chat only), read from Turso session_tokens.
  const tokenRow = res.session?.rows?.[0] || null;
  const tokenLookupFailed = ctx.channel === 'chat' && !!ctx.sessionToken && (!tursoOk || res.session?.ok === false);
  const tokenValid = !!tokenRow && lower(tokenRow.customer_email) === lower(ctx.customerEmail);

  // Identity verification.
  let verified = false;
  let identityCheck = 'unverified';
  let identityNote = '';
  if (ctx.channel === 'email') {
    if (oracle.status === 'ok' && lower(oracle.customer.email) === lower(ctx.customerEmail)) { verified = true; identityNote = 'Sender address matches the account email.'; }
    else if (oracle.status === 'unavailable') { identityCheck = 'failed'; identityNote = 'Oracle lookup unavailable.'; }
    else identityNote = oracle.status === 'not_found' ? 'No account for the sender address.' : 'Lookup not performed.';
  } else if (!ctx.sessionToken) {
    identityNote = 'No session token; customer is not signed in.';
  } else if (tokenLookupFailed) {
    identityCheck = 'failed'; identityNote = 'Turso session lookup failed.';
  } else if (!tokenValid) {
    identityNote = 'Session token is unknown, expired or belongs to another email.';
  } else if (oracle.status === 'unavailable') {
    identityCheck = 'failed'; identityNote = 'Oracle lookup unavailable.';
  } else if (oracle.status === 'ok' && lower(oracle.customer.email) === lower(tokenRow.customer_email) &&
             (!tokenRow.oracle_customer_id || String(tokenRow.oracle_customer_id) === oracle.customer.customer_id)) {
    verified = true; identityNote = 'Valid session token matches the account.';
  } else {
    identityNote = 'Session token does not match an Oracle account.';
  }
  if (verified) identityCheck = 'verified';

  ctx.identity = { verified, check: identityCheck, note: identityNote, sessionValid: tokenValid };
  ctx.account_lookup = oracle.status === 'ok' && !verified ? 'not_requested' : oracle.status;
  ctx.oracleDetail = oracle.detail || null;
  // Unverified Oracle data is dropped here and never reaches an LLM.
  ctx.customer = verified ? { ...oracle.customer, orders: [], tickets: [] } : null;
  if (verified && !ctx.customerName && oracle.customer.full_name) ctx.customerName = oracle.customer.full_name;
  ctx.intent = { account: ACCOUNT_INTENT.test(`${ctx.subject || ''} ${ctx.messageText}`) };
  ctx.tursoLoad = { ok: tursoOk, error: j.turso?.error || null, historyIgnored, conversationExists: !!conv };

  out.push({ json: { ctx } });
}
return out;

// Wrap the ORDS orders response under one key so the 3-way Merge does not clash.
// Mode: Run Once for Each Item.
const code = Number($json.statusCode || 0);
let body = $json.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = null; } }
return { json: { oracleOrders: { ok: code === 200 && Array.isArray(body?.items), status: code || null, items: Array.isArray(body?.items) ? body.items : [], error: code === 200 ? null : (code ? `HTTP ${code}` : ($json.error?.message || 'timeout or network error')) } } };

// Wrap the ORDS tickets response under one key so the 3-way Merge does not clash.
// Mode: Run Once for Each Item.
const code = Number($json.statusCode || 0);
let body = $json.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = null; } }
return { json: { oracleTickets: { ok: code === 200 && Array.isArray(body?.items), status: code || null, items: Array.isArray(body?.items) ? body.items : [], error: code === 200 ? null : (code ? `HTTP ${code}` : ($json.error?.message || 'timeout or network error')) } } };

// ATTACH ACCOUNT DATA: add recent orders and tickets to the verified customer.
// Defensive scrub: drops any payment-like field and masks long digit runs, even
// though the ORDS views already exclude payment columns.
// Mode: Run Once for Each Item.
const ctx = $json.ctx;
const PAYMENT_KEY = /card|cvv|cvc|iban|bic|swift|payment|token|billing|account_number|routing|expir/i;
const luhn = (digits) => {
  let sum = 0;
  for (let i = 0; i < digits.length; i++) {
    let d = Number(digits[digits.length - 1 - i]);
    if (i % 2 === 1) { d *= 2; if (d > 9) d -= 9; }
    sum += d;
  }
  return sum % 10 === 0;
};
// Masks card-like numbers (13-19 digits that pass the Luhn check); keeps tracking numbers.
const maskDigits = (s) => String(s).replace(/\b\d(?:[ -]?\d){12,18}\b/g, (m) => (luhn(m.replace(/\D/g, '')) ? '[redacted card number]' : m));

function scrub(value) {
  if (Array.isArray(value)) return value.map(scrub);
  if (value && typeof value === 'object') {
    const o = {};
    for (const [k, v] of Object.entries(value)) {
      if (PAYMENT_KEY.test(k) || k === 'links') continue;
      o[k] = scrub(v);
    }
    return o;
  }
  return typeof value === 'string' ? maskDigits(value) : value;
}

const orders = $json.oracleOrders || { ok: false, items: [], error: 'not loaded' };
const tickets = $json.oracleTickets || { ok: false, items: [], error: 'not loaded' };

ctx.customer.orders = scrub(orders.items).slice(0, 5);
ctx.customer.tickets = scrub(tickets.items).slice(0, 5);
ctx.accountData = { ordersOk: orders.ok, ticketsOk: tickets.ok, ordersError: orders.error, ticketsError: tickets.error };
// Orders are part of identity-dependent answers: a failed fetch counts as unavailable.
if (!orders.ok) ctx.account_lookup = 'unavailable';

return { json: { ctx } };

// CLAUDE BUILD REQUEST: system prompt (with retrieved FAQ) + user turn (context, history, message).
// Runs again on each retry (input then comes from "⏳ Claude: Backoff").
// Mode: Run Once for Each Item.
const cfg = { ...$('⚙️ CONFIG').first().json, ...($json.ctx?.runtime?.config || {}) };
const nodePrompts = $('📝 PROMPTS').first().json;
const rp = $json.ctx?.runtime?.prompts || {};
const prompts = {
  CLAUDE_SYSTEM: rp.claude_system || nodePrompts.CLAUDE_SYSTEM,
  GEMINI_SYSTEM: rp.gemini_reviewer || nodePrompts.GEMINI_SYSTEM,
  HOLDING_MESSAGE: rp.holding_message || nodePrompts.HOLDING_MESSAGE,
  EMAIL_SIGNATURE: rp.email_signature || nodePrompts.EMAIL_SIGNATURE,
};
const ctx = $json.ctx;
const prev = $json.claudeState || { attempt: 0 };
const attempt = prev.attempt + 1;

// {{snake_case}} variables (admin console) and legacy [[UPPER_CASE]] both work.
const fill = (tpl, vars) => String(tpl || '')
  .replace(/\{\{\s*([a-z][a-z0-9_]*)\s*\}\}/g, (m, k) => (vars[k] !== undefined ? String(vars[k]) : m))
  .replace(/\[\[([A-Z_]+)\]\]/g, (m, k) => (vars[k.toLowerCase()] !== undefined ? String(vars[k.toLowerCase()]) : m));

const faqText = (ctx.faq || []).length
  ? ctx.faq.map((f) => `[FAQ #${f.id}] Q: ${f.question}\nA: ${f.answer}\n(tags: ${f.tags || ''})`).join('\n\n')
  : '(No matching FAQ entries were found for this message.)';

const vars = {
  company_name: cfg.COMPANY_NAME,
  customer_name: ctx.customerName || 'there',
  channel: ctx.channel,
  identity_status: ctx.identity?.verified ? 'verified' : 'unverified',
  account_lookup: ctx.account_lookup,
  faq_context: faqText,
  faq_rows: faqText,
  today: new Date().toISOString().slice(0, 10),
};

const customerContextValue = ctx.customer
  ? JSON.stringify({ identity: 'verified', account_lookup: ctx.account_lookup, customer: ctx.customer }, null, 2)
  : JSON.stringify({ identity: ctx.identity?.verified ? 'verified' : 'unverified', account_lookup: ctx.account_lookup, customer: null, note: 'No account data may be shared in this reply.' }, null, 2);

const customerContext = customerContextValue;
vars.account_context = customerContext;
const historyText = (ctx.history || []).length
  ? ctx.history.map((m) => `[${m.role} ${m.created_at}] ${String(m.body).slice(0, 1500)}`).join('\n')
  : '(No earlier messages in this conversation.)';

const userContent = [
  'CUSTOMER_CONTEXT (labeled account data for the verified customer only):',
  '<customer_context>',
  customerContext,
  '</customer_context>',
  '',
  'CONVERSATION_HISTORY (oldest first):',
  '<conversation_history>',
  historyText,
  '</conversation_history>',
  '',
  `CUSTOMER_MESSAGE (channel: ${ctx.channel}; name: ${ctx.customerName || 'unknown'}; subject: ${ctx.subject || ''}):`,
  '<customer_message>',
  ctx.messageText,
  '</customer_message>',
  '',
  'Write the draft reply now and return only the JSON object.',
].join('\n');

const schema = {
  type: 'object',
  properties: {
    answer: { type: 'string' },
    confidence: { type: 'number' },
    needs_human: { type: 'boolean' },
    reason: { type: 'string' },
    uses_account_data: { type: 'boolean' },
  },
  required: ['answer', 'confidence', 'needs_human', 'reason', 'uses_account_data'],
  additionalProperties: false,
};

const body = {
  model: cfg.CLAUDE_MODEL,
  max_tokens: Number(cfg.MAX_TOKENS) || 1024,
  system: fill(prompts.CLAUDE_SYSTEM, vars),
  messages: [{ role: 'user', content: userContent }],
  output_config: {
    effort: cfg.CLAUDE_EFFORT || 'low',
    format: { type: 'json_schema', schema },
  },
};
if (String(cfg.CLAUDE_REFUSAL_FALLBACK || '').toLowerCase() === 'default') body.fallbacks = 'default';

// Time budget: chat replies must fit inside CHAT_TIMEOUT_MS; email can wait longer.
const budget = Number(cfg.CHAT_TIMEOUT_MS) || 8000;
const remaining = ctx.channel === 'chat' ? ctx.receivedAtMs + budget - Date.now() : 60000;
const timeoutMs = ctx.channel === 'chat' ? Math.max(2000, Math.min(8000, remaining - 2500)) : Number(cfg.LLM_TIMEOUT_MS) || 30000;

return {
  json: {
    ctx,
    claudeState: { attempt, lastError: prev.lastError || null },
    claudeRequest: { body, timeoutMs, userContent, customerContext, historyText, faqText },
  },
};

// CLAUDE PARSE: validate the strict JSON draft and decide whether to retry.
// Retries (exponential backoff) on 408/409/429/5xx/529 and network timeouts, max 3 attempts.
// Mode: Run Once for Each Item. Never throws.
const cfg = { ...$('⚙️ CONFIG').first().json, ...($json.ctx?.runtime?.config || {}) };
const j = $json;
const ctx = j.ctx;
const state = j.claudeState || { attempt: 1 };
const code = Number(j.statusCode || 0);
let body = j.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { /* not JSON */ } }

const claude = { valid: false, answer: '', confidence: 0, needs_human: true, reason: '', uses_account_data: false, error: null, stopReason: null, model: null, httpStatus: code || null };
let retryable = false;

if (code === 200 && body && typeof body === 'object') {
  claude.stopReason = body.stop_reason || null;
  claude.model = body.model || null;
  if (body.stop_reason === 'refusal') {
    claude.error = `Claude declined the request (refusal${body.stop_details?.category ? `: ${body.stop_details.category}` : ''})`;
  } else if (body.stop_reason === 'max_tokens') {
    claude.error = 'Claude hit MAX_TOKENS before finishing the JSON';
  } else {
    const text = (body.content || []).filter((b) => b.type === 'text').map((b) => b.text).join('').trim();
    try {
      const cleaned = text.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '');
      const p = JSON.parse(cleaned);
      const typesOk = typeof p.answer === 'string' && typeof p.confidence === 'number' && typeof p.needs_human === 'boolean' &&
        typeof p.reason === 'string' && typeof p.uses_account_data === 'boolean';
      if (!typesOk) throw new Error('JSON does not match the required fields and types');
      Object.assign(claude, {
        valid: p.answer.trim().length > 0 && Number.isFinite(p.confidence),
        answer: p.answer.trim(),
        confidence: Math.max(0, Math.min(1, p.confidence)),
        needs_human: p.needs_human,
        reason: p.reason.trim(),
        uses_account_data: p.uses_account_data,
      });
      if (!claude.valid) claude.error = 'Empty answer or invalid confidence';
    } catch (e) {
      claude.error = `Malformed JSON from Claude: ${e.message}`;
    }
  }
} else if (code) {
  const msg = body?.error?.message || (typeof body === 'string' ? body.slice(0, 300) : '');
  claude.error = `Anthropic API HTTP ${code}${msg ? `: ${msg}` : ''}`;
  retryable = [408, 409, 429, 500, 502, 503, 504, 529].includes(code);
} else {
  const e = j.error;
  claude.error = `Anthropic API unreachable: ${typeof e === 'string' ? e : e?.message || 'timeout or network error'}`;
  retryable = true;
}

const isChat = ctx.channel === 'chat';
const backoffSec = (isChat ? 0.5 : 1) * 2 ** (state.attempt - 1);
const remaining = isChat ? ctx.receivedAtMs + (Number(cfg.CHAT_TIMEOUT_MS) || 8000) - Date.now() : Infinity;
const retry = !claude.valid && retryable && state.attempt < 3 && remaining > backoffSec * 1000 + 3500;

return {
  json: {
    ctx,
    claudeState: { attempt: state.attempt, retry, backoffSec, lastError: claude.error },
    claude,
    claudeInput: { customerContext: j.claudeRequest?.customerContext, historyText: j.claudeRequest?.historyText, faqText: j.claudeRequest?.faqText },
  },
};

// GEMINI BUILD REQUEST: reviewer sees the same context block plus Claude's draft.
// Runs again on each retry (input then comes from "⏳ Gemini: Backoff").
// Mode: Run Once for Each Item.
const cfg = { ...$('⚙️ CONFIG').first().json, ...($json.ctx?.runtime?.config || {}) };
const nodePrompts = $('📝 PROMPTS').first().json;
const rp = $json.ctx?.runtime?.prompts || {};
const prompts = {
  CLAUDE_SYSTEM: rp.claude_system || nodePrompts.CLAUDE_SYSTEM,
  GEMINI_SYSTEM: rp.gemini_reviewer || nodePrompts.GEMINI_SYSTEM,
  HOLDING_MESSAGE: rp.holding_message || nodePrompts.HOLDING_MESSAGE,
  EMAIL_SIGNATURE: rp.email_signature || nodePrompts.EMAIL_SIGNATURE,
};
const ctx = $json.ctx;
const claude = $json.claude;
const input = $json.claudeInput || {};
const prev = $json.geminiState || { attempt: 0 };
const attempt = prev.attempt + 1;

// {{snake_case}} variables (admin console) and legacy [[UPPER_CASE]] both work.
const fill = (tpl, vars) => String(tpl || '')
  .replace(/\{\{\s*([a-z][a-z0-9_]*)\s*\}\}/g, (m, k) => (vars[k] !== undefined ? String(vars[k]) : m))
  .replace(/\[\[([A-Z_]+)\]\]/g, (m, k) => (vars[k.toLowerCase()] !== undefined ? String(vars[k.toLowerCase()]) : m));
const system = fill(prompts.GEMINI_SYSTEM, {
  company_name: cfg.COMPANY_NAME,
  customer_name: ctx.customerName || 'there',
  channel: ctx.channel,
  identity_status: ctx.identity?.verified ? 'verified' : 'unverified',
  account_lookup: ctx.account_lookup,
  faq_context: input.faqText || '(none)',
  account_context: input.customerContext || 'none',
  today: new Date().toISOString().slice(0, 10),
});

const userText = [
  'KNOWLEDGE_BASE:',
  '<knowledge_base>',
  input.faqText || '(none)',
  '</knowledge_base>',
  '',
  'CUSTOMER_CONTEXT:',
  '<customer_context>',
  input.customerContext || '(none)',
  '</customer_context>',
  '',
  'CONVERSATION_HISTORY:',
  '<conversation_history>',
  input.historyText || '(none)',
  '</conversation_history>',
  '',
  'CUSTOMER_MESSAGE:',
  '<customer_message>',
  ctx.messageText,
  '</customer_message>',
  '',
  "DRAFT (written by the drafting model; its own assessment follows):",
  '<draft>',
  claude.answer,
  '</draft>',
  `Drafting model confidence: ${claude.confidence}; needs_human: ${claude.needs_human}; uses_account_data: ${claude.uses_account_data}; reason: ${claude.reason}`,
  '',
  'Review the draft and return only the JSON object.',
].join('\n');

const body = {
  systemInstruction: { parts: [{ text: system }] },
  contents: [{ role: 'user', parts: [{ text: userText }] }],
  generationConfig: {
    temperature: 0,
    maxOutputTokens: 2048,
    responseMimeType: 'application/json',
    responseSchema: {
      type: 'OBJECT',
      properties: {
        agrees: { type: 'BOOLEAN' },
        confidence: { type: 'NUMBER' },
        issues: { type: 'ARRAY', items: { type: 'STRING' } },
        needs_human: { type: 'BOOLEAN' },
      },
      required: ['agrees', 'confidence', 'issues', 'needs_human'],
      propertyOrdering: ['agrees', 'confidence', 'issues', 'needs_human'],
    },
  },
};

const budget = Number(cfg.CHAT_TIMEOUT_MS) || 8000;
const remaining = ctx.channel === 'chat' ? ctx.receivedAtMs + budget - Date.now() : 60000;
const timeoutMs = ctx.channel === 'chat' ? Math.max(1500, Math.min(8000, remaining - 300)) : Number(cfg.LLM_TIMEOUT_MS) || 30000;

return {
  json: {
    ctx,
    claude,
    claudeInput: input,
    claudeState: $json.claudeState,
    geminiState: { attempt, lastError: prev.lastError || null },
    geminiRequest: {
      url: `https://generativelanguage.googleapis.com/v1beta/models/${encodeURIComponent(cfg.GEMINI_MODEL)}:generateContent`,
      body,
      timeoutMs,
    },
  },
};

// GEMINI PARSE: validate the strict JSON review and decide whether to retry.
// Mode: Run Once for Each Item. Never throws.
const cfg = { ...$('⚙️ CONFIG').first().json, ...($json.ctx?.runtime?.config || {}) };
const j = $json;
const ctx = j.ctx;
const state = j.geminiState || { attempt: 1 };
const code = Number(j.statusCode || 0);
let body = j.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { /* not JSON */ } }

const gemini = { valid: false, agrees: false, confidence: 0, issues: [], needs_human: true, error: null, finishReason: null, httpStatus: code || null };
let retryable = false;

if (code === 200 && body && typeof body === 'object') {
  const cand = body.candidates?.[0];
  gemini.finishReason = cand?.finishReason || null;
  if (body.promptFeedback?.blockReason) {
    gemini.error = `Gemini blocked the prompt: ${body.promptFeedback.blockReason}`;
  } else if (!cand) {
    gemini.error = 'Gemini returned no candidates';
  } else {
    const text = (cand.content?.parts || []).filter((p) => typeof p.text === 'string' && !p.thought).map((p) => p.text).join('').trim();
    try {
      const cleaned = text.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '');
      const p = JSON.parse(cleaned);
      const typesOk = typeof p.agrees === 'boolean' && typeof p.confidence === 'number' && Array.isArray(p.issues) && typeof p.needs_human === 'boolean';
      if (!typesOk) throw new Error('JSON does not match the required fields and types');
      Object.assign(gemini, {
        valid: Number.isFinite(p.confidence),
        agrees: p.agrees,
        confidence: Math.max(0, Math.min(1, p.confidence)),
        issues: p.issues.map((s) => String(s)).filter(Boolean).slice(0, 10),
        needs_human: p.needs_human,
      });
    } catch (e) {
      gemini.error = `Malformed JSON from Gemini: ${e.message}${gemini.finishReason && gemini.finishReason !== 'STOP' ? ` (finishReason ${gemini.finishReason})` : ''}`;
    }
  }
} else if (code) {
  const msg = body?.error?.message || (typeof body === 'string' ? body.slice(0, 300) : '');
  gemini.error = `Google AI Studio HTTP ${code}${msg ? `: ${msg}` : ''}`;
  retryable = [408, 429, 500, 502, 503, 504].includes(code);
} else {
  const e = j.error;
  gemini.error = `Google AI Studio unreachable: ${typeof e === 'string' ? e : e?.message || 'timeout or network error'}`;
  retryable = true;
}

const isChat = ctx.channel === 'chat';
const backoffSec = (isChat ? 0.5 : 1) * 2 ** (state.attempt - 1);
const remaining = isChat ? ctx.receivedAtMs + (Number(cfg.CHAT_TIMEOUT_MS) || 8000) - Date.now() : Infinity;
const retry = !gemini.valid && retryable && state.attempt < 3 && remaining > backoffSec * 1000 + 2000;

return {
  json: {
    ctx,
    claude: j.claude,
    claudeInput: j.claudeInput,
    claudeState: j.claudeState,
    geminiState: { attempt: state.attempt, retry, backoffSec, lastError: gemini.error },
    gemini,
  },
};

// POLICY GUARD: deterministic checks that run before the DECISION IF node.
// Reads the admin-console settings (per-channel threshold, kill switch, business hours,
// blocked keywords) and produces clean booleans for the IF node plus a reason code.
// Mode: Run Once for Each Item. Never throws.
const cfg = { ...$('⚙️ CONFIG').first().json, ...($json.ctx?.runtime?.config || {}) };
const ctx = $json.ctx;
const claude = $json.claude || { valid: false, confidence: 0, needs_human: true, answer: '', error: 'Claude step did not run' };
const gemini = $json.gemini || { valid: false, agrees: false, confidence: 0, issues: [], needs_human: true, error: 'Skipped because the Claude draft was not usable' };

const num = (v, d) => (typeof v === 'number' && Number.isFinite(v) ? v : Number.isFinite(Number(v)) && v !== null && v !== '' ? Number(v) : d);
const base = num(cfg.CONFIDENCE_THRESHOLD, 0.8);
const T = ctx.channel === 'email' ? num(cfg.CONFIDENCE_THRESHOLD_EMAIL, base) : num(cfg.CONFIDENCE_THRESHOLD_CHAT, base);

const luhn = (digits) => {
  let sum = 0;
  for (let i = 0; i < digits.length; i++) {
    let d = Number(digits[digits.length - 1 - i]);
    if (i % 2 === 1) { d *= 2; if (d > 9) d -= 9; }
    sum += d;
  }
  return sum % 10 === 0;
};
const answer = String(claude.answer || '');
const cardLike = (answer.match(/\b\d(?:[ -]?\d){12,18}\b/g) || []).some((m) => luhn(m.replace(/\D/g, '')));
const allowedEmails = new Set([String(ctx.customerEmail || '').toLowerCase(), String(cfg.SUPPORT_FROM_EMAIL || '').toLowerCase()]);
const foreignEmail = (answer.match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g) || []).some((e) => !allowedEmails.has(e.toLowerCase()));

// Kill switch (per channel).
const autoOn = ctx.channel === 'email' ? cfg.AUTO_REPLY_EMAIL !== false : cfg.AUTO_REPLY_CHAT !== false;

// Business hours in the configured time zone.
let outsideHours = false;
const bh = cfg.BUSINESS_HOURS;
if (bh && bh.enabled && bh.days) {
  try {
    const parts = Object.fromEntries(new Intl.DateTimeFormat('en-US', { timeZone: bh.timezone || 'UTC', weekday: 'short', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).formatToParts(new Date()).map((p) => [p.type, p.value]));
    const day = String(parts.weekday || '').slice(0, 3).toLowerCase();
    const hhmm = `${String(parts.hour).padStart(2, '0')}:${String(parts.minute).padStart(2, '0')}`;
    const hours = bh.days[day];
    outsideHours = !hours || hhmm < hours[0] || hhmm >= hours[1];
  } catch (e) {
    outsideHours = false;
  }
}

// Blocked keywords never auto-reply.
const text = `${ctx.subject || ''} ${ctx.messageText}`.toLowerCase();
const keywordHit = (Array.isArray(cfg.BLOCKED_KEYWORDS) ? cfg.BLOCKED_KEYWORDS : []).find((k) => k && text.includes(String(k).toLowerCase()));

// Ordered so the most specific cause becomes the reason code.
const forced = [];
if (!autoOn) forced.push(['kill_switch', `Auto-reply is turned off for ${ctx.channel}`]);
if (outsideHours) forced.push(['outside_hours', 'Received outside business hours']);
if (keywordHit) forced.push(['blocked_keyword', `Message contains the blocked keyword "${keywordHit}"`]);
if (ctx.identity?.check === 'failed' && ctx.intent?.account) forced.push(['policy', `Identity check could not complete (${ctx.identity.note}) and the customer asked about their account`]);
else if (ctx.account_lookup === 'unavailable' && ctx.intent?.account) forced.push(['policy', 'Account lookup unavailable for an account question']);
if (claude.uses_account_data && !ctx.identity?.verified) forced.push(['policy', 'Draft uses account data but the customer is not verified']);
if (cardLike) forced.push(['policy', 'Draft contains a card-like number']);
if (foreignEmail) forced.push(['policy', 'Draft mentions an email address other than the customer or support address']);

const reasons = [];
if (!claude.valid) reasons.push(`Claude response unusable: ${claude.error || 'invalid JSON'}`);
if (!gemini.valid) reasons.push(`Gemini response unusable: ${gemini.error || 'invalid JSON'}`);
if (claude.valid && claude.confidence < T) reasons.push(`Claude confidence ${claude.confidence.toFixed(2)} < ${T}`);
if (gemini.valid && gemini.confidence < T) reasons.push(`Gemini confidence ${gemini.confidence.toFixed(2)} < ${T}`);
if (gemini.valid && !gemini.agrees) reasons.push('Gemini does not agree with the draft');
if (claude.valid && claude.needs_human) reasons.push(`Claude asked for a human: ${claude.reason || 'no reason given'}`);
if (gemini.valid && gemini.needs_human) reasons.push('Gemini asked for a human');
reasons.push(...forced.map((f) => f[1]));

let reasonCode = null;
if (!claude.valid || !gemini.valid) reasonCode = 'parse_error';
else if (forced.length) reasonCode = forced[0][0];
// Claude itself asking for a human means the question is outside what it can answer;
// Claude confident but Gemini objecting is a disagreement.
else if (claude.needs_human) reasonCode = 'unusual_question';
else if (!gemini.agrees || gemini.needs_human) reasonCode = 'models_disagree';
else if (claude.confidence < T || gemini.confidence < T) reasonCode = 'low_confidence';

const priority = reasonCode === 'parse_error' || reasonCode === 'blocked_keyword' || reasonCode === 'policy' ? 'high' : reasonCode === 'outside_hours' ? 'low' : 'normal';
const notifySlack = !(reasonCode === 'outside_hours' && bh && bh.outside_mode === 'holding');

const decision = {
  threshold: T,
  bothValid: claude.valid === true && gemini.valid === true,
  claudeConfidence: claude.valid ? Number(claude.confidence) : 0,
  geminiConfidence: gemini.valid ? Number(gemini.confidence) : 0,
  geminiAgrees: gemini.valid === true && gemini.agrees === true,
  anyNeedsHuman: claude.needs_human === true || gemini.needs_human === true,
  forceHuman: forced.length > 0,
  reasons,
  reasonText: reasons.length ? reasons.join('; ') : 'All checks passed',
  reasonCode,
  priority,
  notifySlack,
};

return { json: { ctx, claude, gemini, decision } };

// AUTO-REPLY FORMAT: final customer-facing text for both channels.
// Email: greeting + answer + signature, as text and HTML. Chat: Markdown + safe HTML.
// Mode: Run Once for Each Item.
const cfg = { ...$('⚙️ CONFIG').first().json, ...($json.ctx?.runtime?.config || {}) };
const sigTpl = $json.ctx?.runtime?.prompts?.email_signature || $('📝 PROMPTS').first().json.EMAIL_SIGNATURE || cfg.SUPPORT_SIGNATURE || '';
const signature = String(sigTpl).replace(/\{\{\s*company_name\s*\}\}/g, cfg.COMPANY_NAME).replace(/\[\[COMPANY_NAME\]\]/g, cfg.COMPANY_NAME);
const j = $json;
const ctx = j.ctx;

const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
function inline(s) {
  return esc(s)
    .replace(/`([^`]+)`/g, '<code>$1</code>')
    .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
    .replace(/(^|[^*])\*([^*\n]+)\*/g, '$1<em>$2</em>')
    .replace(/\[([^\]]+)\]\((https:\/\/[^\s)]+)\)/g, '<a href="$2" target="_blank" rel="noopener noreferrer">$1</a>');
}
// Minimal Markdown → HTML (paragraphs, bullet and numbered lists, bold, italics, code, https links).
function mdToHtml(md) {
  const blocks = String(md).replace(/\r/g, '').split(/\n{2,}/);
  return blocks.map((b) => {
    const lines = b.split('\n');
    if (lines.every((l) => /^\s*[-*•]\s+/.test(l))) return `<ul>${lines.map((l) => `<li>${inline(l.replace(/^\s*[-*•]\s+/, ''))}</li>`).join('')}</ul>`;
    if (lines.every((l) => /^\s*\d+[.)]\s+/.test(l))) return `<ol>${lines.map((l) => `<li>${inline(l.replace(/^\s*\d+[.)]\s+/, ''))}</li>`).join('')}</ol>`;
    return `<p>${lines.map(inline).join('<br>')}</p>`;
  }).join('\n');
}

const firstName = String(ctx.customerName || '').trim().split(/\s+/)[0] || '';
const answer = String(j.claude.answer).trim();
let markdown;
let text;
if (ctx.channel === 'email') {
  const greeting = firstName ? `Hi ${firstName},` : 'Hi,';
  markdown = `${greeting}\n\n${answer}\n\n${signature}`;
  text = markdown.replace(/\*\*([^*]+)\*\*/g, '$1').replace(/\[([^\]]+)\]\((https:[^)]+)\)/g, '$1 ($2)');
} else {
  markdown = answer;
  text = answer;
}

const html = ctx.channel === 'email'
  ? `<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.5;color:#1f2328">${mdToHtml(markdown)}</div>`
  : mdToHtml(markdown);

return { json: { ...j, outcome: 'auto', reply: { markdown, text, html } } };

// HUMAN ESCALATION PREP: the holding reply the customer gets, plus the escalation details
// sent to the admin site (which stores it, applies the SLA and posts the masked Slack alert).
// Mode: Run Once for Each Item.
const cfg = { ...$('⚙️ CONFIG').first().json, ...($json.ctx?.runtime?.config || {}) };
const nodePrompts = $('📝 PROMPTS').first().json;
const rp = $json.ctx?.runtime?.prompts || {};
const j = $json;
const ctx = j.ctx;
const decision = j.decision || { reasonText: 'Escalated', reasonCode: 'parse_error', priority: 'high', notifySlack: true };

const fill = (tpl, vars) => String(tpl || '')
  .replace(/\{\{\s*([a-z][a-z0-9_]*)\s*\}\}/g, (m, k) => (vars[k] !== undefined ? String(vars[k]) : m))
  .replace(/\[\[([A-Z_]+)\]\]/g, (m, k) => (vars[k.toLowerCase()] !== undefined ? String(vars[k.toLowerCase()]) : m));

const firstName = String(ctx.customerName || '').trim().split(/\s+/)[0] || '';
const vars = { company_name: cfg.COMPANY_NAME, customer_name: ctx.customerName || 'there', first_name: firstName || 'there', channel: ctx.channel };
const holding = fill(rp.holding_message || nodePrompts.HOLDING_MESSAGE, vars).trim();
const signature = fill(rp.email_signature || nodePrompts.EMAIL_SIGNATURE || cfg.SUPPORT_SIGNATURE, vars).trim();
const markdown = ctx.channel === 'email' ? `${firstName ? `Hi ${firstName},` : 'Hi,'}\n\n${holding}\n\n${signature}` : holding;

const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const paragraphs = markdown.split(/\n{2,}/).map((p) => `<p>${esc(p).replace(/\n/g, '<br>')}</p>`).join('');
const html = ctx.channel === 'email' ? `<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.5;color:#1f2328">${paragraphs}</div>` : paragraphs;

return {
  json: {
    ...j,
    outcome: 'escalated',
    reply: { markdown, text: markdown, html },
    escalation: {
      reasonCode: decision.reasonCode || 'low_confidence',
      reason: decision.reasonText,
      priority: decision.priority || 'normal',
      notifySlack: decision.notifySlack !== false,
    },
  },
};

// SITE PAYLOAD: what the admin site's /api/internal/send-reply and /api/internal/escalate expect.
// Email: deliver=true, the site sends the reply over SMTP with In-Reply-To/References.
// Chat:  deliver=false, n8n already answered the widget; the site records it.
// Mode: Run Once for Each Item. Input: the Reply Channel item (email) or the Respond to Webhook passthrough (chat).
const j = $json;
const ctx = j.ctx;
const c = j.claude || {};
const g = j.gemini || {};
const d = j.decision || {};
const isEmail = ctx.channel === 'email';

const account = ctx.customer
  ? {
      customer_id: ctx.customer.customer_id,
      full_name: ctx.customer.full_name,
      plan: ctx.customer.plan,
      status: ctx.customer.status,
      orders: (ctx.customer.orders || []).slice(0, 3).map((o) => ({ order_id: o.order_id, order_date: o.order_date, status: o.status, total: o.total, currency: o.currency, carrier: o.carrier })),
    }
  : null;

const payload = {
  requestId: ctx.requestId,
  conversation: {
    id: ctx.conversationId,
    channel: ctx.channel,
    customerEmail: ctx.customerEmail || null,
    customerName: ctx.customerName || null,
    oracleCustomerId: ctx.customer?.customer_id || null,
    subject: ctx.subject || null,
  },
  customerMessage: { body: ctx.messageText, receivedAt: ctx.receivedAt },
  reply: { text: j.reply.text, html: j.reply.html || '' },
  deliver: isEmail,
  email: isEmail
    ? {
        to: ctx.customerEmail,
        subject: ctx.email.replySubject,
        inReplyTo: ctx.email.messageId,
        references: [...(ctx.email.references || []), ctx.email.messageId].filter(Boolean).slice(-20),
        quotedText: ctx.email.quotedText || '',
        quotedHtml: ctx.email.quotedHtml || '',
      }
    : null,
  decision: {
    claude: { answer: c.answer || '', confidence: c.valid ? c.confidence : null, needs_human: c.needs_human, reason: c.reason || '', uses_account_data: !!c.uses_account_data, valid: !!c.valid, error: c.error || null, model: c.model || null },
    gemini: j.gemini ? { agrees: !!g.agrees, confidence: g.valid ? g.confidence : null, issues: g.issues || [], needs_human: g.needs_human, valid: !!g.valid, error: g.error || null } : null,
    threshold: d.threshold ?? null,
    bothValid: !!d.bothValid,
    geminiAgrees: !!d.geminiAgrees,
    anyNeedsHuman: d.anyNeedsHuman !== false,
    forceHuman: !!d.forceHuman,
    reasons: (d.reasons || []).map(String).slice(0, 30),
    reasonCode: j.outcome === 'auto' ? null : (d.reasonCode || null),
  },
  account,
  meta: {
    identity: ctx.identity,
    account_lookup: ctx.account_lookup,
    retrieval: { method: ctx.retrieval?.method, count: ctx.retrieval?.count, keywords: ctx.retrieval?.keywords },
    historyIgnored: !!ctx.tursoLoad?.historyIgnored,
    runtimeSource: ctx.runtime?.source || 'nodes',
  },
};
if (j.outcome !== 'auto') payload.escalation = j.escalation;

return { json: { sitePath: j.outcome === 'auto' ? 'send-reply' : 'escalate', sitePayload: payload, outcome: j.outcome, channel: ctx.channel, requestId: ctx.requestId } };

// TURSO ENCODE: the ONE place that knows the libSQL / Hrana HTTP format.
// Input:  { ctx, turso: { purpose, timeoutMs, statements: [{ key, sql, args }] }, ... }
// Output: same item + tursoRequest { url, timeoutMs, body } for "🗄️ Turso: Pipeline".
// Docs: https://docs.turso.tech/sdk/http/reference  (POST /v2/pipeline)
// Mode: Run Once for Each Item.
const cfg = $('⚙️ CONFIG').first().json;
const t = $json.turso;

const base = String(cfg.TURSO_DATABASE_URL || '')
  .trim()
  .replace(/^libsql:\/\//i, 'https://')
  .replace(/\/+$/, '');

function toValue(v) {
  if (v === null || v === undefined) return { type: 'null' };
  if (typeof v === 'boolean') return { type: 'integer', value: v ? '1' : '0' };
  if (typeof v === 'number') {
    if (!Number.isFinite(v)) return { type: 'null' };
    return Number.isInteger(v) ? { type: 'integer', value: String(v) } : { type: 'float', value: v };
  }
  if (typeof v === 'object') return { type: 'text', value: JSON.stringify(v) };
  return { type: 'text', value: String(v) };
}

const requests = (t.statements || []).map((s) => ({
  type: 'execute',
  stmt: { sql: s.sql, args: (s.args || []).map(toValue), want_rows: true },
}));
requests.push({ type: 'close' });

return {
  json: {
    ...$json,
    tursoRequest: {
      url: `${base}/v2/pipeline`,
      timeoutMs: Number(t.timeoutMs) || 8000,
      keys: (t.statements || []).map((s, i) => s.key || `stmt_${i}`),
      body: { requests },
    },
  },
};

// TURSO DECODE: turns the Hrana response into plain rows, keyed by statement key.
// Never throws: transport or SQL errors become ok:false with a message.
// Output: { ctx, ...caller fields, turso: { purpose, ok, error, results: { <key>: { ok, rows, error, affected, lastInsertRowid } } } }
// Mode: Run Once for Each Item.
const item = $json;
const req = item.tursoRequest || { keys: [] };
const purpose = item.turso?.purpose;

function fromValue(v) {
  if (!v || v.type === 'null') return null;
  if (v.type === 'integer') { const n = Number(v.value); return Number.isSafeInteger(n) ? n : v.value; }
  if (v.type === 'float') return Number(v.value);
  if (v.type === 'blob') return v.base64;
  return v.value;
}

const results = {};
let ok = true;
let error = null;

if (!Array.isArray(item.results)) {
  ok = false;
  const e = item.error;
  error = typeof e === 'string' ? e : (e?.message || e?.description || JSON.stringify(e || item.message || 'No response from Turso'));
  for (const k of req.keys) results[k] = { ok: false, rows: [], error };
} else {
  req.keys.forEach((key, i) => {
    const r = item.results[i];
    if (!r || r.type !== 'ok') {
      const msg = r?.error?.message || 'Statement failed';
      results[key] = { ok: false, rows: [], error: msg };
      // A missing optional FTS table, or admin-console tables, is not a failure.
      if (key !== 'faq_fts' && !key.startsWith('runtime_')) { ok = false; error = error || `${key}: ${msg}`; }
      return;
    }
    const res = r.response?.result || {};
    const cols = (res.cols || []).map((c, ci) => c.name || `col_${ci}`);
    results[key] = {
      ok: true,
      rows: (res.rows || []).map((row) => Object.fromEntries(row.map((v, ci) => [cols[ci], fromValue(v)]))),
      affected: res.affected_row_count ?? 0,
      lastInsertRowid: res.last_insert_rowid != null ? Number(res.last_insert_rowid) : null,
      error: null,
    };
  });
}

const out = { ...item };
delete out.results; delete out.baton; delete out.base_url; delete out.error; delete out.tursoRequest;
out.turso = { purpose, ok, error, results };
return { json: out };
